/* طرق الدفع — صف لكل طريقة، بلا صور */
import "./Skeletons.css";

export default function PayMethodSkeleton(props) {
  const count = Math.max(1, Math.min(8, Number(props.count) || 4));
  const items = [];
  for (let i = 0; i < count; i++) {
    items.push(
      <div className="sk-pay" key={i} aria-hidden="true">
        <div className="sk-row">
          <span className="sk-block sk-round sk-avatar" />
          <span className="sk-block sk-line" style={{ width: "50%" }} />
        </div>
        <span className="sk-block sk-line short" />
      </div>
    );
  }
  return (
    <ul className="inf-payments" role="status" aria-live="polite" aria-label="جارٍ تحميل طرق الدفع" style={{ listStyle: "none", padding: 0 }}>
      {items}
    </ul>
  );
}
