/* ============================================================
   أطياب الجاسم (React) — صفحة قائمة الأمنيات (WishlistPage)

   نفس الكومبوننتين المستعملين في العربة لكن بوضع «wishlist»:
     · ListProductCard mode="wishlist"  → بطاقة المنتج بشارة «في العربة»
       وحالة المخزون وزرّي «أضف للعربة» و«إزالة» (بلا عدّاد كمية).
     · SummaryProduct mode="wishlist"   → الملخّص الذي يتغيّر مع عدد
       المنتجات + «أضف كل القطع للعربة».

   ★ المفضلة في Redux (wishlistSlice) وتُحفظ محلياً في المتصفح.
   ============================================================ */

import { useEffect, useMemo } from "react";
import { Link } from "react-router-dom";
import { PATHS, productPath } from "../routes.js";
import { usePageMeta } from "../usePageMeta.js";
import { useAppDispatch, useAppSelector } from "../redux/hooks.js";
import { pullWishlist, wishlistActions } from "../redux/slices/wishlistSlice.js";
import { selectPerfumesList, selectPerfumesStatus } from "../redux/slices/perfumesSlice.js";
import { selectOudsList, selectOudsStatus } from "../redux/slices/oudsSlice.js";
import { selectIncensesList, selectIncensesStatus } from "../redux/slices/incensesSlice.js";
/* ★ R23: اقتراحات «قد يعجبك» تشمل الأصناف الجديدة */
import { selectMistsList, selectMistsStatus } from "../redux/slices/mistsSlice.js";
import { selectLotionsList, selectLotionsStatus } from "../redux/slices/lotionsSlice.js";
import { selectMukhamariaList, selectMukhamariaStatus } from "../redux/slices/mukhamariaSlice.js";
import { selectHairList, selectHairStatus } from "../redux/slices/hairSlice.js";
import { selectWishlistProducts, selectCartIds } from "../redux/selectors.js";
import { CardSkeleton } from "../components/Skeletons/index.js";
import "../components/Skeletons/Skeletons.css";
import ListProductCard from "../components/Product/ListProductCard.jsx";
import SummaryProduct from "../components/Product/SummaryProduct.jsx";
import { Money } from "../components/Source/Money.jsx";
import { Icon, ProductImage } from "../components/Source/Icons.jsx";

const SUGGESTIONS_MAX = 3;

export default function WishlistPage() {
  usePageMeta({ route: "wishlist", titleAr: "قائمة الأمنيات", titleEn: "Wishlist" });

  const dispatch = useAppDispatch();
  const customerId = useAppSelector(function (s) {
    return (s.user && s.user.auth && s.user.auth.customerId) || null;
  });
  const language = useAppSelector(function (s) {
    return (s.ui && s.ui.language) || "ar";
  });
  const wishError = useAppSelector(function (s) {
    return (s.wishlist && s.wishlist.wishError) || null;
  });
  const syncError = useAppSelector(function (s) {
    return !!(s.wishlist && s.wishlist.syncError);
  });

  /* ★ v17-W2: جلب/مصالحة المفضلة عند كل دخول للصفحة (الحساب الحالي فقط —
     الضيف محلي خالص بلا شبكة). المصالحة تستبدل ولا ترفع محذوفات جهاز آخر. */
  useEffect(
    function () {
      if (customerId) dispatch(pullWishlist());
    },
    [dispatch, customerId]
  );

  const products = useAppSelector(selectWishlistProducts);
  const cartIds = useAppSelector(selectCartIds);
  const wishIds = useAppSelector(function (s) {
    return s.wishlist.ids;
  });

  const perfumesPool = useAppSelector(selectPerfumesList);
  const oudsPool = useAppSelector(selectOudsList);
  const incensesPool = useAppSelector(selectIncensesList);
  /* ★ R23: الأصناف الجديدة في الاقتراحات وبوابة السكيلتون */
  const mistsPool = useAppSelector(selectMistsList);
  const lotionsPool = useAppSelector(selectLotionsList);
  const mukhamariaPool = useAppSelector(selectMukhamariaList);
  const hairPool = useAppSelector(selectHairList);
  /* ★ R19: الكتالوج يُجلب عند أول دخول — وقبله كانت الصفحة تحكم «فارغة»
     فورًا ثم تقفز البطاقات. سكيلتون بحجم الشبكة حتى يصل الكتالوج. */
  const catalogLoading = [useAppSelector(selectPerfumesStatus), useAppSelector(selectOudsStatus), useAppSelector(selectIncensesStatus), useAppSelector(selectMistsStatus), useAppSelector(selectLotionsStatus), useAppSelector(selectMukhamariaStatus), useAppSelector(selectHairStatus)].some(function (st) {
    return st === "idle" || st === "loading";
  });
  const pool = useMemo(
    function () {
      return perfumesPool.concat(oudsPool, incensesPool, mistsPool, lotionsPool, mukhamariaPool, hairPool);
    },
    [perfumesPool, oudsPool, incensesPool, mistsPool, lotionsPool, mukhamariaPool, hairPool]
  );

  /* اقتراحات: أول المنتجات غير الموجودة في القائمة (عطور ثم بخور) */
  const suggestions = useMemo(
    function () {
      return pool
        .filter(function (p) {
          return wishIds.indexOf(p.id) === -1;
        })
        .slice(0, SUGGESTIONS_MAX);
    },
    [wishIds, pool]
  );

  return (
    <section className="container view ct wl" id="wishlistView">
      <div className="ct-top">
        <Link className="ct-back" to={PATHS.perfumes}>
          <Icon name="back" strokeWidth={2} />
          <span>متابعة التسوق</span>
        </Link>
        <span className="ct-crumb">
          حسابي / <b>قائمة الأمنيات</b>
        </span>
      </div>

      <header className="ct-head">
        <span className="eyebrow">حسابي</span>
        <h1>
          قائمة <span className="gold-text">الأمنيات</span>
        </h1>
        <p className="ct-sub">
          كل منتج وضعت عليه قلباً محفوظ في مفضلتك على هذا الجهاز — تصفّحه وقتما تشاء، أضف ما تريد إلى العربة، وأزل ما لم يعد يعجبك.
        </p>
      </header>

      {/* ★ v17-W2: أخطاء التعديل/المزامنة ظاهرة مع إعادة محاولة — لا ابتلاع */}
      {wishError ? (
        <div className="ct-empty" style={{ padding: "12px 16px", marginBottom: "12px" }} role="alert">
          <p>{language === "en" ? wishError.textEn : wishError.text}</p>
          <div className="wl-empty-actions">
            <button className="btn-ghost" type="button" onClick={function () { dispatch(wishlistActions.wishErrorClear()); }}>
              {language === "en" ? "Dismiss" : "إخفاء"}
            </button>
          </div>
        </div>
      ) : null}
      {syncError && customerId ? (
        <div className="ct-empty" style={{ padding: "12px 16px", marginBottom: "12px" }} role="alert">
          <p>{language === "en" ? "Could not refresh your wishlist — showing this device's list." : "تعذّر تحديث المفضلة — تُعرض قائمة هذا الجهاز."}</p>
          <div className="wl-empty-actions">
            <button className="btn-primary" type="button" onClick={function () { dispatch(pullWishlist()); }}>
              {language === "en" ? "Retry" : "إعادة المحاولة"}
            </button>
          </div>
        </div>
      ) : null}

      {catalogLoading && products.length === 0 ? (
        <CardSkeleton count={3} />
      ) : products.length === 0 ? (
        <div className="ct-empty wl-empty">
          <span className="ct-empty-ic">
            <Icon name="heart" fill="currentColor" strokeWidth={1.6} />
          </span>
          <h3>قائمة الأمنيات فارغة</h3>
          <p>
            لم تضع قلباً على أي منتج بعد. اضغط على القلب أعلى صورة العطر أو البخور ليُحفظ هنا، فيكون جاهزاً بين يديك في
            زيارتك القادمة.
          </p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.perfumes}>
              تصفّح العطور
            </Link>
            <Link className="btn-ghost" to={PATHS.incense}>
              تصفّح البخور
            </Link>
          </div>
        </div>
      ) : (
        <div className="ct-grid">
          <div className="ct-items">
            {products.map(function (p) {
              return (
                <ListProductCard
                  mode="wishlist"
                  product={p}
                  inCart={cartIds.indexOf(p.id) !== -1}
                  key={p.id}
                />
              );
            })}
          </div>

          <aside className="ct-aside">
            <SummaryProduct mode="wishlist" />

            {suggestions.length ? (
              <div className="wl-sug">
                <h3>
                  <Icon name="spark" strokeWidth={1.6} />
                  <span>قد يعجبك أيضاً</span>
                </h3>
                <ul className="wl-sug-list">
                  {suggestions.map(function (p) {
                    return (
                      <li className="wl-sug-item" key={p.id}>
                        <Link className="wl-sug-thumb" to={productPath(p.id)}>
                          <ProductImage product={p} />
                        </Link>
                        <div className="wl-sug-body">
                          <Link className="wl-sug-name" to={productPath(p.id)}>
                            {p.name}
                          </Link>
                          <span className="wl-sug-sub">{p.desc}</span>
                          <span className="wl-sug-price">
                            <Money sar={p.price} />
                          </span>
                        </div>
                      </li>
                    );
                  })}
                </ul>
              </div>
            ) : null}
          </aside>
        </div>
      )}
    </section>
  );
}
